import json
import re
from typing import Dict, List, Tuple

SECTION_RE = re.compile(r"^\[(.+)]\s*$")
CHOICE_RE = re.compile(r"^\s*(\d+)\.\s*(.+?)\s*->\s*(\S+)\s*$")


def _split_arrow(line: str) -> Tuple[str, str]:
    """Split a line on the last '->' into (left, target)."""
    if "->" not in line:
        return line.strip(), ""
    left, target = line.rsplit("->", 1)
    return left.strip(), target.strip()


def _parse_line_node(line: str) -> Tuple[str, str, str]:
    """Return (speaker, text, target)."""
    left, target = _split_arrow(line)
    speaker = ""
    text = left
    if ":" in left:
        speaker_part, text_part = left.split(":", 1)
        speaker = speaker_part.strip()
        text = text_part.strip()
    return speaker, text, target


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    lines = text.splitlines()

    sections: List[Tuple[str, List[str]]] = []
    current_id = None
    current_lines: List[str] = []

    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        match = SECTION_RE.match(line)
        if match:
            if current_id is not None:
                sections.append((current_id, current_lines))
            current_id = match.group(1).strip()
            current_lines = []
        else:
            current_lines.append(line)

    if current_id is not None:
        sections.append((current_id, current_lines))

    nodes: Dict[str, Dict[str, str]] = {}
    edges: List[Dict[str, str]] = []

    for node_id, content_lines in sections:
        choice_edges = []
        non_choice_lines = []
        for line in content_lines:
            choice_match = CHOICE_RE.match(line)
            if choice_match:
                choice_text = choice_match.group(2).strip()
                choice_target = choice_match.group(3).strip()
                choice_edges.append((choice_text, choice_target))
            else:
                non_choice_lines.append(line)

        if choice_edges:
            nodes[node_id] = {
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "choice",
            }
            for choice_text, choice_target in choice_edges:
                edges.append({
                    "from": node_id,
                    "to": choice_target,
                    "text": choice_text,
                })
        else:
            # Allow multiple line statements; join them for the node text.
            combined = " ".join(non_choice_lines).strip()
            speaker, text_value, target = _parse_line_node(combined)
            nodes[node_id] = {
                "id": node_id,
                "text": text_value,
                "speaker": speaker,
                "type": "line",
            }
            if target:
                edges.append({
                    "from": node_id,
                    "to": target,
                    "text": "",
                })

    # Add placeholders for referenced but undefined targets.
    for edge in edges:
        target_id = edge["to"]
        if target_id and target_id not in nodes:
            nodes[target_id] = {
                "id": target_id,
                "text": "",
                "speaker": "",
                "type": "line",
            }

    # Keep only nodes reachable from the first node.
    if sections:
        start_id = sections[0][0]
        reachable = set()
        stack = [start_id]
        adjacency = {}
        for edge in edges:
            adjacency.setdefault(edge["from"], []).append(edge["to"])

        while stack:
            current = stack.pop()
            if current in reachable:
                continue
            reachable.add(current)
            for nxt in adjacency.get(current, []):
                if nxt not in reachable:
                    stack.append(nxt)

        nodes = {node_id: node for node_id, node in nodes.items() if node_id in reachable}
        edges = [edge for edge in edges if edge["from"] in reachable and edge["to"] in reachable]

    return {
        "nodes": list(nodes.values()),
        "edges": edges,
    }


def _escape_dot_label(value: str) -> str:
    if value is None:
        return ""
    escaped = value.replace("\\", "\\\\").replace('"', '\\"')
    # Ensure ASCII output for dot labels.
    escaped = escaped.encode("unicode_escape").decode("ascii")
    return escaped


def to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    node_lines = []
    for node in graph.get("nodes", []):
        node_id = node.get("id", "")
        node_type = node.get("type", "line")
        speaker = node.get("speaker", "")
        text = node.get("text", "")
        if node_type == "choice":
            label = f"{node_id}"
            shape = "diamond"
        else:
            label = f"{node_id}"
            if speaker:
                label += f"\\n{speaker}: {text}"
            else:
                label += f"\\n{text}"
            shape = "box"
        node_lines.append(f'  "{_escape_dot_label(node_id)}" [label="{_escape_dot_label(label)}", shape={shape}];')

    edge_lines = []
    for edge in graph.get("edges", []):
        from_id = edge.get("from", "")
        to_id = edge.get("to", "")
        label = edge.get("text", "")
        if label:
            edge_lines.append(
                f'  "{_escape_dot_label(from_id)}" -> "{_escape_dot_label(to_id)}" [label="{_escape_dot_label(label)}"];'
            )
        else:
            edge_lines.append(
                f'  "{_escape_dot_label(from_id)}" -> "{_escape_dot_label(to_id)}";'
            )

    dot_lines = ["digraph Dialogue {", "  rankdir=LR;", "  node [fontname=\"Helvetica\"];"]
    dot_lines.extend(node_lines)
    dot_lines.extend(edge_lines)
    dot_lines.append("}")
    return "\n".join(dot_lines)


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as handle:
        text = handle.read()

    graph = parse_script(text)

    with open("/app/dialogue.json", "w", encoding="utf-8") as handle:
        json.dump(graph, handle, indent=2, ensure_ascii=True)

    with open("/app/dialogue.dot", "w", encoding="utf-8") as handle:
        handle.write(to_dot(graph))


if __name__ == "__main__":
    main()
